#include "engine.hpp"
#include <iostream>
#include <cmath>
using namespace uaa;
void check(bool value,const char* message){if(!value)throw std::runtime_error(message);}
int main(int argc,char** argv){try{
 check(argc==3,"Expected data and temporary directory");Engine e(argv[1],argv[2]);e.createBase("Research",50,14);std::vector<int> scientists;for(int i=0;i<int(e.state["personnel"].size());++i)if(e.state["personnel"][i]["role"]=="scientist")scientists.push_back(i);check(scientists.size()==10,"Starter scientists");
 check(!e.researchAvailable("research_intel_sectoid")&&!e.startResearch("research_intel_sectoid").ok,"Undiscovered alien intelligence is hidden and cannot start");check(!e.researchAvailable("research_autopsy_sectoid")&&!e.researchAvailable("research_ufo_ufo-craft"),"Autopsy and wreck projects require actual finds");auto initial=e.state;e.state["liveAliens"]["sectoid"]=1;check(e.researchAvailable("research_intel_sectoid"),"Captured live alien unlocks intelligence");e.state=initial;e.state["research"]["research_autopsy_sectoid"]=1.;check(e.researchAvailable("research_intel_sectoid"),"Completed autopsy unlocks intelligence");e.state=initial;e.state["corpses"]["sectoid"]=1;check(!e.researchAvailable("research_autopsy_sectoid"),"Corpse alone does not bypass biology prerequisite");e.state["research"]["research_alien_biology"]=1.;check(e.researchAvailable("research_autopsy_sectoid"),"Corpse and biology unlock autopsy");e.state=initial;
 check(!e.researchAvailable("research_alien_biology")&&!e.researchAvailable("research_alien_materials")&&!e.researchAvailable("research_psionics"),"Alien specimens and technology are unavailable before recovery");e.state["wrecks"]["ufo-craft"]=1;check(e.researchAvailable("research_alien_materials"),"Recovered wreck unlocks materials analysis");
 check(e.startResearch("research_basic_lab").ok,"Select first project");e.advance(12);check(e.state["research"]["research_basic_lab"]==0.,"Unassigned scientists must not research automatically");
 auto before=e.state;check(e.startResearch("research_basic_lab").ok&&e.state==before,"Reselecting a started project is not an error and preserves progress");
 for(int i=0;i<5;++i)check(e.assignScientist("research_basic_lab",scientists[i],true).ok,"Assign chosen scientist");check(e.assignScientist("research_basic_lab",scientists[0],true).ok&&e.researchTeam("research_basic_lab").size()==5,"Duplicate click does not duplicate staff");
 check(e.startResearch("research_alien_materials").ok,"Select another project");before=e.state;check(!e.assignScientist("research_alien_materials",scientists[0],true).ok&&e.state==before,"Scientist cannot work on two projects");check(!e.assignScientist("research_basic_lab",0,true).ok&&e.state==before,"Pilot cannot be assigned as scientist");
 for(int i=5;i<10;++i)check(e.assignScientist("research_alien_materials",scientists[i],true).ok,"Independent second team");e.advance(72);check(std::abs(e.state["research"]["research_basic_lab"].get<double>()-.5)<1e-9,"Five of ten reference scientists complete half of 72-hour project");check(std::abs(e.state["research"]["research_alien_materials"].get<double>()-.15)<1e-9,"Second project uses only its own team");
 e.save(1);Engine loaded(argv[1],argv[2]);check(loaded.load(1).ok&&loaded.researchTeam("research_basic_lab")==e.researchTeam("research_basic_lab"),"Assigned teams survive load");loaded.advance(72);check(loaded.state["research"]["research_basic_lab"]==1.,"Research completes with assigned staff");check(loaded.scientistProject(scientists[0]).empty(),"Finished project releases scientist availability");check(loaded.assignScientist("research_alien_materials",scientists[0],true).ok,"Released scientist can join another project");
 for(int person:scientists)loaded.assignScientist("research_alien_materials",person,false);double progress=loaded.state["research"]["research_alien_materials"];loaded.advance(24);check(loaded.state["research"]["research_alien_materials"]==progress,"Removing all scientists pauses only that project");
 before=e.state;check(!e.startResearch("research_autopsy_sectoid").ok&&e.state==before,"DUMMY prerequisite and specimen requirements enforced");e.state["research"]["research_alien_biology"]=1.;e.state["corpses"]["sectoid"]=1;check(e.startResearch("research_autopsy_sectoid").ok,"Delivered specimen and completed prerequisite unlock autopsy");
 auto invalid=readJson(e.userDir/"save-1.json");invalid["researchStaff"]["research_alien_materials"].push_back(scientists[0]);writeJson(e.userDir/"save-2.json",invalid);before=loaded.state;check(!loaded.load(2).ok&&loaded.state==before,"Duplicate active assignment in a save is rejected transactionally");
 invalid=readJson(e.userDir/"save-1.json");invalid.erase("researchStaff");writeJson(e.userDir/"save-3.json",invalid);check(loaded.load(3).ok&&loaded.researchTeam("research_basic_lab").empty(),"Legacy research saves remain loadable for explicit staff assignment");
 Engine queue(argv[1],fs::path(argv[2])/"queue");queue.createBase("Queue",50,14);check(queue.startResearch("research_basic_lab").ok&&queue.startResearch("research_ballistics").ok,"Queue two research projects");check(queue.researchQueue()==Json::array({"research_basic_lab","research_ballistics"}),"Research queue preserves insertion order");queue.startResearch("research_basic_lab");check(queue.researchQueue().size()==2,"Queue does not duplicate selected project");for(int scientist:scientists)queue.assignScientist("research_basic_lab",scientist,true);auto planned=queue.researchSchedule();double firstHours=queue.researchQuote("research_basic_lab")["hours"],secondHours=queue.researchQuote("research_ballistics")["hours"];check(planned[0]["finishInHours"]==firstHours&&planned[1]["startInHours"]==firstHours&&planned[1]["finishInHours"]==firstHours+secondHours,"Research queue shows each item completion time including waiting");Engine jump(argv[1],fs::path(argv[2])/"research-jump");jump.state=queue.state;jump.advance(firstHours+secondHours);check(jump.researchQueue().empty(),"Research queue consumes remaining time across successive projects");queue.advance(queue.researchQuote("research_basic_lab")["hours"]);check(queue.researchTeam("research_ballistics").size()==10&&queue.researchQueue()==Json::array({"research_ballistics"}),"Released scientists continue to next queued project");queue.save(1);Engine next(argv[1],fs::path(argv[2])/"queue");check(next.load(1).ok&&next.researchQueue()==queue.researchQueue(),"Research queue survives reload");next.advance(next.researchQuote("research_ballistics")["hours"]);check(next.researchQueue().empty()&&next.state["research"]["research_ballistics"]==1.,"Queued research completes in order");
 std::cout<<"PASS: project selection, explicit scientists, independent teams, duplicate/role rejection, completion and release, prerequisites, staffing saves and legacy compatibility\n";return 0;
 }catch(const std::exception& error){std::cerr<<"FAIL: "<<error.what()<<"\n";return 1;}}
